sources.ModalBridge.ets:
export class ModalBridge {
 finish(): void { this.controller.close() }
 reset(): void { this.controller.reset() }
}

sources.ConfirmPanel.ets:
import { ModalBridge } from './ModalBridge'
@Component
export struct ConfirmPanel {
 bridge: ModalBridge = new ModalBridge()
 build() {
  Button('Confirm').onClick(() => {
   this.bridge.finish()
  })
 }
}

